41	@Service
42	public class ClinicServiceImpl implements ClinicService {
43	
44	    /**
45	     * Number of owners that must already carry a day's registration date before a
46	     * further owner registered that day is flagged with a bulk signup warning.
47	     */
48	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
