103	    @Transactional(readOnly = true)
104	    public Collection<Visit> findAllVisits() throws DataAccessException {
105	        return visitRepository.findAll();
106	    }
107	
108	    @Override
109	    @Transactional
110	    public void deleteVisit(Visit visit) throws DataAccessException {
111	        visitRepository.delete(visit);
112	    }
113	
114	    @Override
115	    @Transactional(readOnly = true)
116	    public Vet findVetById(int id) throws DataAccessException {
117	        return findEntityById(() -> vetRepository.findById(id));
118	    }
119	
120	    @Override
121	    @Transactional(readOnly = true)
122	    public Collection<Vet> findAllVets() throws DataAccessException {
123	        return vetRepository.findAll();
124	    }
125	
126	    @Override
127	    @Transactional
128	    public void saveVet(Vet vet) throws DataAccessException {
129	        vetRepository.save(vet);
130	    }
131	
132	    @Override
133	    @Transactional
134	    public void deleteVet(Vet vet) throws DataAccessException {
135	        vetRepository.delete(vet);
136	    }
137	
138	    @Override
139	    @Transactional(readOnly = true)
140	    public Collection<Owner> findAllOwners() throws DataAccessException {
141	        return ownerRepository.findAll();
142	    }
143	
144	    @Override
145	    @Transactional(readOnly = true)
146	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
147	        if (lastName != null) {
148	            return ownerRepository.findByLastName(lastName, pageable);
